def node(values: list[bytes]) -> (Bytes, TreeNode):
    sz = len(values)

    if sz == 0:
        return _ZERO_HASH, TreeNode("0")

    elif sz == 1:
        return values[0], TreeNode((values[0]).hex())

    else:
        mid = (sz + 1) // 2

        left = values[:mid]
        right = values[mid:]

        left_node, left_root = node(left)
        right_node, right_root = node(right)

        node_val = Hash.blake2b(_NODE_PREFIX + left_node + right_node)

        return node_val, TreeNode(node_val.hex(), left_root, right_root)


