def print_trace(values: OpaqueHashes):
    for val in values:
        print(val.hex(), end="  ")


def verify_proof(
    trace: Vector[OpaqueHash], leaf: Vector[OpaqueHash], leaf_index: int
) -> OpaqueHash:
    """
    Merkle Proof Verification Function (not provided in GP)

    Args:
        trace: Sequence of nodes depicting path of a tree to a particular index
        leaf: leaf node to prove
        leaf_index: Node Index
    Returns:
        Verification Result
    """
    self = BMRFunctions()

    root = leaf
    for sibling in reversed(trace):
        if leaf_index % 2 == 0:
            root = self._node_fn(TypedVector([root, sibling])).unwrap()
        else:
            root = self._node_fn(TypedVector([sibling, root])).unwrap()
        leaf_index = leaf_index // 2

    print("NEW ROOOT", root.hex())
    return OpaqueHash(root)
